     "1. 직원분들은 융통성 있게 소통 잘해주시고 친절하셔서 만족합니다. 2. 현재까지 자습때 많이 졸앗는데 감독관님이 깨주셨을 때가 거의 없거나 적었습니다. 졸음을 못 깬걸 감독관님 탓을 하는건 아닙니다만 옆 학생들도 조는데 깨우러 오지 않으실 때가 많았고 특정 감독관님을 찝어 말하는게 아닙니다. 졸음 관리가 살짝 부족해보입니다. 그런데 또 감독관님이 자주 입실하시는게 적잖이 집중이 끊길 때가 있긴 했어서 쉽사리 문의 드리기가 어려운 사항입니다. 3. 이코딩 스탠딩 신청 관련입니다. 예약을 받는 것도 아닌데 앞사람 시간이 끝나자마자 신청 가능 상태도 되지 않고 바로 다음 사람이 점유해버려서 제가 신청을 못한 상황이 많았습니다. 웹, 이코딩 둘다 해당합니다. 제 기기가 느린건지 모르겠는데 굉장히 불편했습니다.",
