     "지원실 선생님이나 다른 직원분들 모두 너무 친절하시고 잘 대해 주시는데 한 분만 유독,..     일요일에 거의 하루종일 계시는 분입니다. 40대 후반에서 50대 초중반으로 보이고 사각형 안경끼시는 아저씨이신데,  저 뿐만 아니라 다른 학생들한테도 틱틱대며 말하십니다. 다른 직원분들이나 선생님들께서는 지원실로 부르실 때 존댓말로 존중해주시면서 부르시는데 그 분은 ○○○.8층으로. 이렇게 부른다거나 학생 말을 인상을 쓰면서 중간에 가로채면서 말씀하십니다.  저희가 이 학원 내에서는 학생이지만 다들 성인인데 개들 대하듯 강압적이십니다. 다른 분들처럼 친절하게 대해 주시는건 바라지도 않으니 적어도 존중받고 싶습니다. 일요일마다 그 아저씨직원분 때문에 너무 스트레스 받습니다.  그 외 모든 관리는 정말 만족합니다 ",
     "건의 하고 싶은 점 1.2. 화장실 악취 및 화장실 환기 자주요청 드립니다..  진짜 생선 썩은 비린내에 양치하면서 구역질 나와요 학생들이 자주 안다니는수업시간에 감독관님들께서좀 자체적으로 문을 개방해주시고  수시로 확인하셨으면 좋겠습니다. 2. 수요일 토요일 일요일에계신 파랑셔츠감독관님께민원 사항 있습니다. 감독관님들께서 학생들 졸음깨우러 다니시는거 그거 다 너무 고생하신다는 것은 알고 있습니다. 하지만 이분은돌아다니시는 횟수나 아이들을 잠깨울때펜촉으로 나무 책상을 탁탁 치면서 소음이 발생하게 하고 다니십니다. 어떤 친구가 2번째졸았을땐 화나셨는데 주체를 못하시고 반 온 전체가 울리게 펜을 신경질적으로 치는 모습을 옆에서지켜보고 있었는데 솔직히제공부 흐름이 깨지고 지금까지 강안에서 있으면서 관리 측면에선 최고라고 생각했는데 학생들에게 반말을 하신다거나 자주 착각과 오해를 하시는데 좀 개선해주셨으면 합니다. 또한가지 제  개인적인 일인데 제가 이때 장염에걸린지도 모르고 갑자기 스탠딩에서 있다가 그때가아직 5분 밖에 지나지 않을때였는데 그래서 당연히 그냥 화장실을 갔다왔습니다 알고보니 일을 마친후 와보니 다른 친구가 왔을정도로 전 화장실에서 시간이 그렇게 흘렀는지도 몰라서 연신 사과를 했습니다 근데 그분께서 갑자기 정색하시며 저한테 친구들있는 공간에서 전 분명히 화장실을 갔다왔고 시간이 이정도로걸릴줄은 몰랐다 앞으로는 책은 저쪽에 넣어놓고 가겠다고 말씀드렸지만 , 계속 반복적으로 제가 배가많이 아팠다고 말씀을 드렸는데 계속왜 화장실에오래있냐하면서 저에게는 수치심이 들게 만드셨습니다 아직도 그걸듣고 있던 친구들이 눈빛이 생각나면서아직도 수치심들어요 거기다가 대고 제가 큰일을 봐서 몰랐습니다 할 수도 없는 일이고.. 정말 너무 불쾌했습니다 3.평일날 키 크시고 머리 7:3인 분께서는 관리 정말 철저하게 잘하시는데 한가지요청사항이 있습니다. 제발 주간깨기 나눠주실때 탁타악 던지지 말아주세요. 아무리 그래도 소리나게계속 던지시는걸 가져가려하니 좀 불쾌해요. 4. 주간깨기 그리고 좀오류 없게 개선좀부탁ㄷ립니다. 함수 그래프 쓰면서 해야하는데 오류가 있다고 패드화면에서만 보고 풀라니요.,,.5.급식 지도해주시는 분들 모두 감사합니다 2층 여자안경쓰신 분 어느순간부터 이미 앞에 딱 붙엇는데 자꾸만 신경질적으로 붙으세요 붙으세요 하는데 첨엔 괜찮았는데 이것도 계속 듣자하니 너무 괴로워요 그 톤으로 듣기에요.6. 별관은 특히 하원할때 먼저좀 시켜주세요.. 진짜로 엘베 타는 친구들이 보통 8,9층인데 저희는 그거 기다리고 또 내려서 6층이나 8층하고 내려와야하는데 사람 복도 계단에 꽉채워져 있는데 하원하고 나서 밖을 나오면 10분이 더 딜레이 되고 그래요. 유두리 있게 부탁드리겠습니다 별관또 이동이 하여간 귀찮은데 거기다가 늦게 하원시켜주면 진짜 ....힘들어요 정말 7. 그리고 책상이나 의자는 소독이 어떻게 되어가나요? 책상 그래도 2주에 한번은 소독하나요? 8. 그리고학생  여자분들께 요청 사항이 있는데 여름되면 더워서 옷도 얇아지고 짧아질텐데 너무 노출이 심한 옷은 지양해달라고 꼭 지원실에서 말씀 부탁드립니다 9.그리고 남자 학생들한테는 선행반때부터 겪은 고충인데 제발 양치할때 그 토할 것같은 소리 화장실에서만 내달라고 해주세요.. 저 공용 개수대까지 그 소리하면 정작 쉬고 자기자습해야하는데 그 역한 소리에 자꾸 방해되고 듣기 너무 힘들어요. 진짜.. 그래도 요청사항이 좀 많았지만 꼭 개선되었으면 좋겠습니다. 감사합니다 항상 수고하십니다",
     "피드백 시간에 강의듣게 해주셨으면 좋겠습니다. 수업 내용에서 약간 보충이 필요한 부분을 강의로 듣는 것인데...왜 금지하시는지 모르겠습니다. 그날 과목의 강의듣는 건 허락해주셨으면 합니다(사설 강의 포함)   그리고 떨어진거 주워주는거 정도는....좀 봐주십쇼....안그래도 너무 좁아 죽겠는데 어떻게 무시하고 가요...감독관님께 유사대화행위라고 지적받았는데 너무하다고 생각했어요...ㅜㅜ  마지막으로 학사생들 외박 월 2회로 늘려주시면 안되나요?ㅜㅜ잉 ",
