     "우선 지원실 선생님들과 다른 모든 감독관님들은 친절하시고 좋습니다. 그러나 토요일 일요일에 근무하시는 남자 감독관님에 대하여 건의 드리고 싶은 부분이 있습니다. 첫번째로 문을 벌컥벌컥 열고 들어오십니다. 자는 학생들을 깨울때도 손가락으로 책상을 조용히 흔들거나 깨우는 것이 아닌 동작을 일부로 크게하시고 펜으로 엄청 시끄럽게 탁탁 치시면서 깨웁니다. 공부를 하다가 그 소리에 놀라고 거슬린 적이 한두번이 아닙니다. 그리고 계단을 다니실때도 엄청 시끄럽게 쿵쿵 거리면서 다니십니다. 스탠딩을 사용할 때 너무 시끄럽습니다. 교실에서는 학생들이 자지 않는 것을 분명 확인하였는데도 일부로 자기를 보라는듯이 몸을 부풀리고 틈사이를 다니십니다. 그 과정에서 학생들의 발을 밟고 가방을 발로 차면서 일절 미안하다 혹은 신경쓰는 기색이 보이지 않습니다. 오히려 발을 밟힌건 저인데 째려보며 가십니다. 두번째로 말투가 상당히 공격적이고 무례합니다. 친하다고 생각하는건지 아니면 친근하게 대해주고 싶으신 건지는 모르겠지만 딱히 잘못한게 아닌 그냥 물어보는 말에도 본인은 위압적이라고 생각하는지 반말을 계속하며 상당히 기분나쁜 어투와 어조로 학생들에게 말을 하십니다. 그런 말을 듣는 사람 입장에선 상당히 불쾌합니다. 더불어 제가 생각했을때 방송은 지원실의 공식적인 입장을 전달하는 역할을 한다고 생각합니다. 그러한 방송에서 마저 자신보다 상급자가 퇴근을 한 날은 반말을 하며 방송을 합니다. 정말 어이없었던건 상급자가 있다면 반말을 하지 않고 존대를 하며 방송을 합니다. 일요일 자습을 잘 다니고 있었는데 그분 하나때문에 일요일 자습이 도저히 하고 싶지 않습니다. 솔직히 말씀드리면 이제 막 졸업한 고등학생들 상대로 자신의 권위를 내세우며 우월감을 느끼고 있는 거 같은 느낌이 강하게 들 정도입니다. 이것 외에도 공부할 때 정말 많이 거슬리고 불쾌하고 신경쓰입니다. 이 점은 꼭 조취를 취해주셨으면 하는 바램입니다. 진심으로 간곡히 부탁드립니다. ",
