     "1)일요일 자습날 유독 양치에 대한 규제가 의미없이 심합니다.학생들입장에서는 양치 행굴 곳 찾으로 가는건데 왜 규제하시는지 이해가 안갑니다.물론 주말 자습이라 학생들 풀어지지 않도록 지도하시는 의도는 알고있습니다. 다만, 오히려 영양가 없는 단속은 역효과가 나는 것 같습니다. 2) 이동 명단을 적는 목적은 교실에서 벗어나는, 불필요한 이동을 줄이기 위한 것으로 알고있습니다. 하지만, 한 감독관님은 스탠딩 끝난 후, 질의 혹은 상담 이후 화장실 이용도 모두 명단 작성을 진행하셨습니다. 감독관님들 마다 기준이 다르시다보니 학생들 입장에서 억울한 상황이 발생할 수밖에 없습니다. 전체적인 지도방식을 확실하게 통일해주시면 좋겠습니다. 3) 졸음관리의 중요성을 잘 알고 있습니다. 학생들이 학습에 몰입할 수 있도록 꼼꼼하게 관리해주시는건 좋지만, 졸음을 떨쳐내지 못하는 소수를 반복적으로 깨우기 위해, 적게는 30명 많게는 60명의 학생이 있습 교실에 들어와 수십명이 밀집되어 있는 좁은 통로를 지나서 집중 못하는 한 학생을 깨우는게 과연 옳은가요? 감독선생님도, 학생들도 매번 불쾌하고 눈이 찌푸려지는 상황이 발생할 수 밖에 없습니다. 물론, 그렇다고 해서 졸음관릴,ㄹ 안할 수도 없고 앞서 말한 상황을 학원측에서 모른다고 생각하지도 않습니다. 학생 당 한 교시에 깨우는 횟수를 정해서 다수가 최대한 덜 몰입이 깨질 수 있도록 방안을 마련하셨으면 좋겠습니다.  ",
