     "국어 주간깨기는 없나요? 필요합니다",
     "주간깨기 비용이 별도로 지불되고 있는 사실을 모르고 있었습니다. 시중에 판매되고 있는주간지와 비교해도 저렴하다고 보기 어려운 가격으로 보입니다. 그럼에도 불구하고 프린트 상태나 가독성과 같은 퀄리티적인 부분이 학생을 전혀 고려하지 않게 되어있어서 실망스럽습니다. 반복학습의 효과를 떠나서,흑백 프린트 묶음 20장에 대한 구매의사를 밝힐 수 있다면 절대 사지 않을 것 같습니다.수학 문제 풀 공간도 없고, 인쇄오류로 문제는 누락되고, 같은 지문 여러번 반복 출력되는데, 학생들이 우선순위로 두기 어렵지 않나 싶습니다. 물론 학습에 아주 큰 지장이 있다고 보기 어려우실 수 있지만,저를 포함한 학생들이 주간깨기 참여에 더 비중을 두고, 반복학습의 효과를 확실하게 받아들일 수 있도록 신경써주시면 감사하겠습니다. ",
