     "괴목별로 모아져있으면 더 보기 편할 것 같다",
     "주간깨기에 관해서 건의드릴 사항입니다. 우선 주간깨기에 pf테스트 문제는 없어도 될 것 같습니다. Pf테스트가 끝나고 대부분의 선생님들이 오답과 질의 응답을 실시를 해주시고, 테스트가 끝나고 오답을 안하는 학생은 제 생각엔 아마 없을 것 같아서 드리는 말씀입니다. 그리고 주간깨기에 pf테스트 양까지 포함하다보니 양이 많아져서 주간깨기 퀄리티 자체가 굉장히 떨어지는 일도 발생하는ㄴ 것 같습니다. 두번째로 물론 이건 학생이 건의할사항은 아니지만 가격입니다 다른 학원에 비해 퀄리티가 굉장히 떨어지는건 죄송합니다만 사실입니다. 그리고 이퀄리티에 이가격은 사실 아니라고 봅니다, 대한민국 수험생이라면 오답은 필수의 영역입니다. 이 학원의 특성상 공부 경험이 없는 학생들을 위해 주간깨기 같은 오답 프로그램응 실시 한다는것은 매우 좋은 취지인 것 같습니다만 문제를 복사 붙여넣기하고 다시푸는 방식은 사실 본인이 전에 풀었던 문제 찾아서 다시 풀면 해결될 일입니다. 사실 맘만 같아선 주간깨기를 없애고 차라리 본인 오답노트를 만들어 제출하는 프로그램을 건의하고 싶습니다만 그렇게되면 공부 양 조절응 못하는 학생들에게도 문제가 생기고 이학원이 오랫동안 유지한 프로그램이 흐트러지는 것이기 때문에 건의하지는 않겠습니다. 다만 주간깨기의 가격문제와  퀄리티 문제는 이학원이 최우선적으로 해결해야될 사항이라고 저는 생각합니다.",
