     "PF성적이 잘 안 나와 속상해서 질답시간때 상담을 했었는데 백종수 선생님께서 시험지를 꼼꼼하게 분석해주시고 피드백 해주셔서 덕분에 방향을 다시 잡을 수 있었어요! 그리고 수업시간에 선생님만의 스킬을 알려주셔서 국매깨 풀때 적용했더니 평소보다 시간도 많이 단축되었어요! 감사합니다!앞으로도 진짜 열심히 할게요 잘 부탁드려요",
     "수업이 항상 도움되고 학생들한테 신경을 많이 써주시는게 느껴져서 너무좋아요",
     "피드백 선생님의 풀이가 너무 친절하시고 뭐든게 다 준비되어 있는 거 같아 너무 든든함",
     "선생님이 세심하시고 학생들에게 애정을 많이 가지고 계신다는 느낌을 받아서 좋았습니다. 다만 선생님께서 수업시간이 부족하다고 하시면서 영상을 올려주시게 되었다고 말씀하셨는데 그런것치곤 공지사항에 너무 많은 시간을 쏟고 계신게 아닌가 싶습니다. 매번 공지사항을 확실히 전달해주시고 그 지시사항대로 따르게 이끌어주시는건 좋지만 수업시간이 한타임에 70분밖에 안되는데 그 중 평균적으로 10~25분 정도를 공지사항에 할애하시니 그부분이 개선되면 더 좋을 것 같습니다. 그 외엔 없습니다. 제생각엔 숙제 공지 올려주시는 것처럼 게시판에 공지하고 수업전엔 빠르게 언급하고 넘어가는방식이 괜찮지 않을까? 싶습니다.(매번 수업시간에 배워가는게 정말 많은데 소중한 선생님의 수업 시간을 흘려보내는 것 같아서 아쉬워서 건의해봅니다.)",
     "학생들이 진심으로 잘 되셨으면 하는 마음이 느껴져서 더 열심히 하게 된 것 같습니다",
     "늘 학생들이 이해할 수 있게 쉽고 재밌는 예시를 들어 수업해 주시고 꼼꼼하고 친절한 해설이 있는 교재를 만들어주셔서 정말 만족스럽습니다. PF 테스트 또한 진짜 시험처럼 연습할 수 있어 정말 도움이 많이 됩니다. 질문을 하러 가면 학생마다 문제를 푸는 버릇을 고쳐주시기도 하고 학생 개개인에 맞게 상담지와 점수를 확인하여 어떻게 하면 실력을 늘릴 수 있을지 함께 고민해 주셔서 정말 감사합니다. 수업시간이 부족해 피드백 선생님도 수업을 추가로 해주시고, 추가 수업 영상을 올려 주시는게 쉽지 않은 일임에도 해주셔서 감사합니다!",
     "곶미남 백종수 선생님은 신이에요",
     "일주일 중 수요일이 가장 기다려지게 만들어주셨습니다. 센스 있으시고 학생들과 소통을 최대한 하시려는게 숨통 트이고 특히 만족스럽습니다.   개인적으로 저는 국어 공부법 콤플렉스가 있어서 혼자 공부법을 찾아서 뭐든 독립적으로 하는 공부에 대한 집착이 있었고 또 그렇게 하는게 맞다고 생각하고는 어리석게도 늘 그걸 시도하지 못하고 있었습니다. 그런데 선생님께서 적극적으로 학생들 한명한명에게 맞는 전략을 찾아주시고 이끌어주겠다고 말씀하신걸 듣고, 그 집념을 잠시 접고 선생님을 믿어보기로 했습니다. 물론 모든 공부는 결국 스스로 터득하는게(입에 넣어진 걸 소화하는게) 맞고 책임도 제가 지는게 맞지만 저는 올해 선생님과 선생님의 국어에 대한 투시력을 믿고 따르는 것을 선택하겠습니다. 애초에 한번 실패해 재수하는 입장이면 그게 맞다는 생각도 들었습니다.   아직 몇개월 되지 않았지만 가까운 곳에서 정말 감사히 배우고 있고, 제가 작년 실패한 이유와 잘못된 습관을 찾아 부호화하면서,  앞으로 이끌어주시는만큼 따라가도록 노력해보겠습니다.",
